// Gemeinsame Helfer (werden in beide Code-Nodes eingebettet)
function parseNode(name){
  try {
    const item = $(name).first().json || {};
    const v = JSON.parse((item.data != null ? item.data : 'null') || 'null');
    return (v && typeof v === 'object') ? v : {};
  } catch (e) { return {}; }
}
function stripHtml(h){
  return String(h || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ').trim();
}
function toTs(v){ if (v == null) return 0; const n = (typeof v === 'number') ? v : Date.parse(String(v)); return isFinite(n) ? n : 0; }
function genText(g){
  if (!g || typeof g !== 'object') return '';
  const parts = [];
  if (g.fields && typeof g.fields === 'object'){
    Object.keys(g.fields).forEach(k => {
      const v = g.fields[k];
      if (v != null && String(v).trim()) parts.push(k + ': ' + String(v).trim());
    });
  }
  if (g.styleText) parts.push(String(g.styleText));
  if (g.wishes) parts.push(String(g.wishes));
  return parts.join('\n');
}
function newestVersionHtml(vs){
  let list = [];
  if (Array.isArray(vs)) list = vs.filter(Boolean);
  else if (vs && typeof vs === 'object') list = Object.values(vs).filter(Boolean);
  if (!list.length) return '';
  list = list.slice().sort((a, b) => toTs(a && a.ts) - toTs(b && b.ts));
  const v = list[list.length - 1] || {};
  return String(v.html || v.text || v.content || '');
}
// Kandidaten aus allen Knoten einsammeln (defensiv gegen null/fehlende Felder)
function collectCandidates(docs, orgs, drive, inbox){
  const cands = [];
  Object.keys(docs).forEach(id => {
    const d = docs[id]; if (!d || typeof d !== 'object') return;
    const org = (d.orgId && orgs[d.orgId] && orgs[d.orgId].name) ? String(orgs[d.orgId].name) : '';
    const title = String(d.title || 'Dokument');
    const bodyRaw = (genText(d.gen) + '\n' + stripHtml(newestVersionHtml(d.versions))).trim();
    cands.push({ quelle: 'docDocuments', id, title, org,
      head: (title + ' ' + (d.docType || '') + ' ' + org).toLowerCase(),
      body: bodyRaw.toLowerCase(), bodyRaw, ts: toTs(d.updatedAt || d.createdAt) });
  });
  Object.keys(drive).forEach(id => {
    const d = drive[id]; if (!d || typeof d !== 'object') return;
    const title = String(d.titel_final || d.dateiname || 'Datei');
    const bodyRaw = String(d.textauszug || '').trim();
    cands.push({ quelle: 'driveDocs', id, title,
      head: (title + ' ' + (d.dateiname || '')).toLowerCase(),
      body: bodyRaw.toLowerCase(), bodyRaw, ts: toTs(d.aktualisiert || d.erstellt),
      mimeType: d.mimeType || undefined, downloadUrl: d.downloadUrl || undefined });
  });
  Object.keys(inbox).forEach(id => {
    const n = inbox[id]; if (!n || typeof n !== 'object') return;
    const title = String(n.dateiname || 'Eingang');
    const bodyRaw = String(n.text || '').trim();
    cands.push({ quelle: 'driveInbox', id, title,
      head: title.toLowerCase(),
      body: bodyRaw.toLowerCase(), bodyRaw, ts: toTs(n.erstellt),
      mimeType: n.mimeType || undefined });
  });
  return cands;
}
function scoreAndSort(cands, tokens){
  const now = Date.now();
  cands.forEach(c => {
    let s = 0;
    tokens.forEach(t => { if (c.head.includes(t)) s += 4; if (c.body.includes(t)) s += 1.5; });
    if (tokens.length && s === 0){ c._score = 0; return; }
    const ageDays = c.ts ? (now - c.ts) / 86400000 : 9999;
    c._score = s + Math.max(0, 1.5 - ageDays / 60); // Rezenz-Bonus
  });
  const hits = tokens.length ? cands.filter(c => c._score > 0) : cands.slice();
  hits.sort((a, b) => (b._score - a._score) || (b.ts - a.ts));
  return hits;
}
function tokenize(q){ return String(q || '').toLowerCase().split(/[^a-zäöüéèàß0-9]+/).filter(t => t.length >= 2); }

// ── /search: case-insensitive Volltextsuche ueber alle Knoten ──
try {
  const body = $('Webhook search').first().json.body || {};
  const tokens = tokenize(body.query);
  const limit = Math.max(1, Math.min(25, Number(body.limit) || 8));
  const cands = collectCandidates(
    parseNode('docDocuments lesen'), parseNode('docOrgs lesen'),
    parseNode('driveDocs lesen'), parseNode('driveInbox lesen'));
  const hits = scoreAndSort(cands, tokens);
  function snippet(c){
    const src = c.bodyRaw || '';
    if (!src) return c.quelle === 'docDocuments' ? '' : 'PDF/Datei, kein Textauszug vorhanden.';
    let pos = -1;
    for (const t of tokens){ pos = src.toLowerCase().indexOf(t); if (pos >= 0) break; }
    const start = Math.max(0, pos < 0 ? 0 : pos - 60);
    return (start > 0 ? '… ' : '') + src.slice(start, start + 180).trim() + (src.length > start + 180 ? ' …' : '');
  }
  const results = hits.slice(0, limit).map(c => {
    const r = { quelle: c.quelle, id: c.id, title: c.title, snippet: snippet(c) };
    if (c.mimeType) r.mimeType = c.mimeType;
    if (c.downloadUrl) r.downloadUrl = c.downloadUrl;
    return r;
  });
  return [{ json: { results, count: results.length } }];
} catch (e) {
  return [{ json: { results: [], count: 0 } }];
}

