// ── /read-document: exakter Eintrag per id ODER bester Treffer per query ──
try {
  const body = $('Webhook read-document').first().json.body || {};
  const id = body.id != null ? String(body.id) : '';
  const tokens = tokenize(body.query);
  const docs = parseNode('RD docDocuments lesen');
  const orgs = parseNode('RD docOrgs lesen');
  const drive = parseNode('RD driveDocs lesen');
  const inbox = parseNode('RD driveInbox lesen');

  function compose(quelle, key){
    if (quelle === 'docDocuments'){
      const d = docs[key]; if (!d || typeof d !== 'object') return null;
      const org = (d.orgId && orgs[d.orgId] && orgs[d.orgId].name) ? String(orgs[d.orgId].name) : '';
      const title = String(d.title || 'Dokument');
      const lines = ['Dokument: ' + title
        + (d.docType ? ' (' + d.docType + ')' : '')
        + (org ? ', Organisation: ' + org : '')
        + (d.status ? ', Status: ' + d.status : '')];
      const gt = genText(d.gen); if (gt) lines.push(gt);
      const vh = stripHtml(newestVersionHtml(d.versions)); if (vh) lines.push(vh);
      return { ok: true, quelle, id: key, title, text: lines.join('\n\n').slice(0, 6000) };
    }
    if (quelle === 'driveDocs'){
      const d = drive[key]; if (!d || typeof d !== 'object') return null;
      const title = String(d.titel_final || d.dateiname || 'Datei');
      let text = String(d.textauszug || '').trim();
      if (!text) text = 'PDF/Datei, kein Textauszug vorhanden.' + (d.downloadUrl ? ' Download: ' + d.downloadUrl : '');
      const r = { ok: true, quelle, id: key, title, text: text.slice(0, 6000) };
      if (d.mimeType) r.mimeType = d.mimeType;
      if (d.downloadUrl) r.downloadUrl = d.downloadUrl;
      return r;
    }
    if (quelle === 'driveInbox'){
      const n = inbox[key]; if (!n || typeof n !== 'object') return null;
      const title = String(n.dateiname || 'Eingang');
      let text = String(n.text || '').trim();
      if (!text) text = 'Datei im Eingang, kein Textauszug vorhanden.';
      const r = { ok: true, quelle, id: key, title, text: text.slice(0, 6000) };
      if (n.mimeType) r.mimeType = n.mimeType;
      return r;
    }
    return null;
  }

  if (id){
    const direct = compose('docDocuments', id) || compose('driveDocs', id) || compose('driveInbox', id);
    return [{ json: direct || { ok: false, reason: 'nicht gefunden' } }];
  }
  if (!tokens.length) return [{ json: { ok: false, reason: 'id oder query erforderlich' } }];
  const hits = scoreAndSort(collectCandidates(docs, orgs, drive, inbox), tokens);
  if (!hits.length) return [{ json: { ok: false, reason: 'nicht gefunden' } }];
  const best = hits[0];
  return [{ json: compose(best.quelle, best.id) || { ok: false, reason: 'nicht gefunden' } }];
} catch (e) {
  return [{ json: { ok: false, reason: 'nicht gefunden' } }];
}

// read-mail: reine Input-Validierung — bewusst KEIN Secret-/Env-Check.
// Browser rufen ohne Secret auf (siehe docs/polaris-module.md, Sicherheit/
// Härtung) und der Zugriff auf Umgebungsvariablen ist in dieser n8n-Instanz
// gesperrt ('access to env vars denied'). Fehlt die id → saubere JSON-Antwort.
try {
  const b = $json.body || {};
  const id = String(b.id || '').trim();
  if (!id) return [{ json: { ok: false, error: 'no id' } }];
  return [{ json: { ok: true, id: id } }];
} catch (e) { return [{ json: { ok: false, error: 'no id' } }]; }

// Gmail-Antwort defensiv normalisieren (verschiedene n8n-Gmail-Formate:
// simplify-Top-Level-Felder ODER payload.headers[]-Array). Wirft nie.
try {
  const j = $json || {};
  if (j.error) return [{ json: { ok: false, error: 'Mail nicht gefunden' } }];
  function header(name){
    const hs = (j.payload && Array.isArray(j.payload.headers)) ? j.payload.headers
      : (Array.isArray(j.headers) ? j.headers : []);
    const h = hs.find(function(x){ return x && String(x.name || '').toLowerCase() === name.toLowerCase(); });
    return h ? String(h.value || '') : '';
  }
  function strip(s){ return String(s == null ? '' : s).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim(); }
  return [{ json: {
    ok: true,
    id: String(j.id || $('Validate read-mail').first().json.id || ''),
    from: String(j.from || j.From || header('From') || ''),
    to: String(j.to || j.To || header('To') || ''),
    subject: String(j.subject || j.Subject || header('Subject') || ''),
    date: String(j.date || j.Date || header('Date') || ''),
    text: strip(j.textPlain || j.text || j.textHtml || j.snippet || '').slice(0, 4000)
  } }];
} catch (e) { return [{ json: { ok: false, error: 'Mail nicht gefunden' } }]; }

// compose-mail: Validierung. SICHERHEIT: dieser Zweig legt AUSSCHLIESSLICH
// einen Gmail-ENTWURF an (Gmail-Node: resource=draft, operation=create) —
// es wird NIEMALS gesendet. Kein Env-Zugriff, keine eigenen HTTP-Requests.
try {
  const b = $json.body || {};
  const text = String(b.body || '').trim();
  if (!text) return [{ json: { ok: false, error: 'kein Text' } }];
  return [{ json: {
    ok: true,
    to: String(b.to || '').trim().slice(0, 200),
    subject: (String(b.subject || '').trim() || 'Von Polaris diktiert').slice(0, 200),
    body: text.slice(0, 10000)
  } }];
} catch (e) { return [{ json: { ok: false, error: 'kein Text' } }]; }

// Draft-Antwort → {ok, draftId, to, subject, note}. Wirft nie.
try {
  const v = $('Validate compose').first().json;
  const j = $json || {};
  if (j.error) return [{ json: { ok: false, error: 'Entwurf konnte nicht angelegt werden' } }];
  const draftId = String(j.id || (j.message && j.message.id) || '');
  return [{ json: { ok: true, draftId: draftId, to: v.to || '', subject: v.subject || '',
    note: 'Als Entwurf gespeichert — nicht gesendet' } }];
} catch (e) { return [{ json: { ok: false, error: 'Entwurf konnte nicht angelegt werden' } }]; }
